$new_node_path="E:\work\合肥\大屏\jifangdaping\node_modules\.pnpm\crc32@0.2.2\node_modules\crc32\bin\node_modules;E:\work\合肥\大屏\jifangdaping\node_modules\.pnpm\crc32@0.2.2\node_modules\crc32\node_modules;E:\work\合肥\大屏\jifangdaping\node_modules\.pnpm\crc32@0.2.2\node_modules;E:\work\合肥\大屏\jifangdaping\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
