  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/e/work/合肥/大屏/jifangdaping/node_modules/.pnpm/crc32@0.2.2/node_modules/crc32/bin/node_modules:/mnt/e/work/合肥/大屏/jifangdaping/node_modules/.pnpm/crc32@0.2.2/node_modules/crc32/node_modules:/mnt/e/work/合肥/大屏/jifangdaping/node_modules/.pnpm/crc32@0.2.2/node_modules:/mnt/e/work/合肥/大屏/jifangdaping/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../../../../../crc32@0.2.2/node_modules/crc32/bin/runner.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../../../../../crc32@0.2.2/node_modules/crc32/bin/runner.js" $args
  }
  $ret=$LASTEXITCODE
